package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import java.util.regex.*;
/** Direct recall of two exact equivalents; legacy numeric percentage conversion is separate. */
public final class FractionDecimalPercentRecall {
 private FractionDecimalPercentRecall(){}
 public static final String ID="fractionDecimalPercentRecall",VERSION="fraction-decimal-percent-recall-v1";
 public static final Catalog.Skill SKILL=new Catalog.Skill(ID,"분수·소수·백분율 대응값",6,1,1,"","fractionPercentRecall",100,"","분수와 값이 같은 소수와 백분율 값을 떠올려 쓴다.");
 public static final Set<Integer> SELECTED_DENOMINATORS=Set.of(2,4,5,10,20,25,50,100);
 private static final Pattern SOURCE=Pattern.compile("([0-9]{1,20})/([0-9]{1,20})와 값이 같은 소수와 백분율 값을 쓰세요\\.\\n순환소수는 반복되는 부분을 괄호로 표시하세요\\.");
 public static boolean supports(String id){return ID.equals(id);}
 public static String prompt(String n,String d){return n+"/"+d+"와 값이 같은 소수와 백분율 값을 쓰세요.\n순환소수는 반복되는 부분을 괄호로 표시하세요.";}
 public record Givens(String rawNumerator,String rawDenominator,BigInteger numerator,BigInteger denominator,Rational value){}
 public static Givens read(Question q){if(q==null||!supports(q.skillId)||q.prompt==null)return null;Matcher m=SOURCE.matcher(q.prompt);if(!m.matches())return null;BigInteger n=new BigInteger(m.group(1)),d=new BigInteger(m.group(2));if(d.signum()==0)return null;return new Givens(m.group(1),m.group(2),n,d,new Rational(n,d));}
 public static Rational numericInput(String input){if(input==null||input.length()>120)return null;String raw=input.trim();return raw.contains(".")?FractionDecimalRecall.exactInput(input):RepresentationConversions.integerInput(input);}
 private static Rational target(String expected){if(expected==null||expected.length()>120||!expected.matches("[+-]?[0-9]+(?:/[+-]?[0-9]+)?"))return null;String[] p=expected.split("/",-1);try{return new Rational(new BigInteger(p[0]),p.length==1?BigInteger.ONE:new BigInteger(p[1]));}catch(RuntimeException invalid){return null;}}
 public static boolean acceptsStep(String value,String expected){Rational actual=numericInput(value),wanted=target(expected);return actual!=null&&actual.equals(wanted);}
 static Checker.Result check(Question q,List<String> answers){Givens g=read(q);if(g==null)return new Checker.Result(Checker.Status.INPUT_NEEDED,-1,"문제 확인 필요");if(answers==null||answers.size()!=2)return new Checker.Result(Checker.Status.INPUT_NEEDED,-1,"답 입력 필요");for(int i=0;i<2;i++){Rational actual=numericInput(answers.get(i));if(actual==null)return new Checker.Result(Checker.Status.INPUT_NEEDED,i,"수 입력 확인 필요");Rational expected=i==0?g.value:g.value.mul(Rational.of(100));if(!actual.equals(expected))return new Checker.Result(Checker.Status.WRONG_ANSWER,i,"이 답 확인");}return new Checker.Result(Checker.Status.CORRECT,-1,"계산 확인 완료");}
 private static void step(StudyGuide h,String text,String before,Rational expected){h.step(text,before,"",expected.toString());h.frames.get(h.frames.size()-1).inputFormat=ID;}
 public static StudyGuide guide(Question q){Givens g=read(q);if(g==null)return null;StudyGuide h=new StudyGuide().transfer(false);h.teachingVersion=VERSION;step(h,"문제의 분자를 쓰세요.","분자 n = ",new Rational(g.numerator,BigInteger.ONE));step(h,"문제의 분모를 쓰세요.","분모 d = ",new Rational(g.denominator,BigInteger.ONE));step(h,"분수와 값이 같은 소수를 쓰세요.","소수 v = ",g.value);step(h,"분수와 값이 같은 백분율 값을 쓰세요.","백분율 (%) = ",g.value.mul(Rational.of(100)));return h;}
 public static Map<String,String> references(Question q,int stage,List<String> entries){StudyGuide h=guide(q);if(h==null||entries==null||stage<2||stage>3)return Map.of();Map<String,String> out=new LinkedHashMap<>();for(int i=0;i<(stage==3?3:2);i++)if(i<entries.size()&&new HelpPlan.Step(h.frames.get(i)).accepts(entries.get(i)))out.put(h.frames.get(i).before,entries.get(i));return out;}
 static Question make(int n,int d){if(!SELECTED_DENOMINATORS.contains(d)||n<0||n>d)throw new IllegalArgumentException("Selected fraction decimal percentage recall scope");Question q=new Question(ID,prompt(Integer.toString(n),Integer.toString(d)),"",Rational.of(n,d).decimalText(),Rational.of(n,d).mul(Rational.of(100)).decimalText());q.kind=ID;q.answerFormat=ID;q.labels=new String[]{"소수 값","백분율 (%)"};q.stepSupport=false;q.decimal=true;q.studyGuide=guide(q);return q.withInputs(n,d);}
 private static int family(Givens g){return g.denominator.equals(BigInteger.valueOf(2))||g.denominator.equals(BigInteger.valueOf(4))?0:g.denominator.equals(BigInteger.valueOf(5))?1:2;}
 static Question next(Random random,CurriculumLimits limits,Map<String,Integer> recent){List<Question> all=new ArrayList<>();List<List<Question>> fresh=List.of(new ArrayList<Question>(),new ArrayList<Question>(),new ArrayList<Question>());int[] seen=new int[3];for(int d:new int[]{2,4,5,10,20,25,50,100})for(int n=0;n<=d;n++){Question q=make(n,d);all.add(q);if(!limits.allows(q))continue;int f=family(read(q));if(recent.containsKey(q.signature()))seen[f]++;else fresh.get(f).add(q);}int least=Integer.MAX_VALUE;for(int f=0;f<3;f++)if(!fresh.get(f).isEmpty())least=Math.min(least,seen[f]);List<List<Question>> families=new ArrayList<>();for(int f=0;f<3;f++)if(!fresh.get(f).isEmpty()&&seen[f]==least)families.add(fresh.get(f));if(!families.isEmpty()){List<Question> group=families.get(random.nextInt(families.size()));return group.get(random.nextInt(group.size()));}return IndexedQuestionSupply.choose(all.size(),all::get,random,limits,recent);}
}
